// Parsear CSV y agrupar por REF_PATRON
const csvText = items[0].json.data ?? items[0].json.body ?? items[0].json;
const lines = String(csvText).split(/\r?\n/);

function slugify(str) {
  return String(str || "")
    .toLowerCase()
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
}

function resolveCategoryId(categoriaPadre, categoriaTexto) {
  if (
    categoriaTexto === "Textil" ||
    ["Calzado", "Bañadores"].includes(categoriaTexto) ||
    ["Casual", "Equipaciones"].includes(categoriaPadre)
  ) return "textil";

  if (
    categoriaPadre === "Equipamiento" ||
    [
      "Redes","Vestuarios","Equipamiento agua","Colchonetas","Baloncesto","Fútbol 11 y 7",
      "Fútbol sala - Balonmano","Voleibol","Banquillos","Gimnasia","Tenis","Protecciones columnas",
      "Otros deportes","Pádel"
    ].includes(categoriaTexto)
  ) return "instalaciones";

  if (["Psicomotricidad", "Juegos"].includes(categoriaPadre)) return "material-escolar";
  return "deportes";
}

const groups = new Map();

for (let i = 1; i < lines.length; i++) {
  const line = lines[i].trim();
  if (!line) continue;

  const fields = line.split(";");
  const clean = fields.map(f => f.replace(/"/g, "").trim());

  const refPatron   = clean[0] || null;
  const refVariante = clean[1] || null;
  const ean         = clean[2] || null;
  const stock       = parseInt(clean[3], 10) || 0;
  const name        = clean[4] || "";
  const marca       = clean[5] || null;
  const imagen      = clean[6] || null;
  const categoriaTexto = clean[7] || null;
  const categoriaPadre = clean[8] || null;
  const color       = clean[9] || null;
  const talla       = clean[10] || null;

  if (!refPatron) continue;

  if (!groups.has(refPatron)) {
    const categoryId = resolveCategoryId(categoriaPadre || "", categoriaTexto || "");
    const subcategory = `${categoriaPadre || ""} > ${categoriaTexto || ""}`;
    const baseSlug = slugify(name);
    const skuPadre = `J${refPatron}`;
    const slug = `${baseSlug}-${slugify(skuPadre)}`;

    groups.set(refPatron, {
      product: {
        proveedor: "jim_sports",
        ref_proveedor: refPatron,
        sku_interno: skuPadre,
        name,
        marca,
        imagen,
        categoryId,
        subcategory,
        slug,
        published: true,
        activo: true,
        visible_web: true
      },
      variants: []
    });
  }

  const variantSku = refVariante ? `J${refPatron}-${refVariante}` : `J${refPatron}-BASE`;

  groups.get(refPatron).variants.push({
    proveedor: "jim_sports",
    ref_proveedor: refPatron,
    ref_variante: refVariante,
    sku_interno: variantSku,
    ean,
    stock,
    color,
    talla,
    imagen
  });
}

const out = [];
for (const [refPatron, g] of groups.entries()) {
  out.push({ json: { type: "product", ...g.product } });
  for (const v of g.variants) {
    out.push({ json: { type: "variant", ...v } });
  }
}

return out;

// Extraer REF_PATRON únicas para llamar a la API
const uniqueRefs = new Set();

for (const item of items) {
  if (item.json.ref_proveedor) {
    uniqueRefs.add(item.json.ref_proveedor);
  }
}

return Array.from(uniqueRefs).map(ref => ({
  json: { ref_proveedor: ref }
}));

// Extraer precios de la API y aplicar márgenes
function calcularPrecioConMargen(precioBase) {
  const precio = parseFloat(precioBase);

  if (isNaN(precio) || precio <= 0) return { precioBase: 0, precioFinal: 0 };

  let multiplicador;

  if (precio < 50) {
    multiplicador = 1.50;
  } else if (precio < 100) {
    multiplicador = 1.47;
  } else if (precio < 200) {
    multiplicador = 1.43;
  } else if (precio < 400) {
    multiplicador = 1.38;
  } else {
    multiplicador = 1.30;
  }

  return {
    precioBase: parseFloat(precio.toFixed(2)),
    precioFinal: parseFloat((precio * multiplicador).toFixed(2))
  };
}

const results = [];

for (const item of items) {
  // Si la llamada API falló, saltar
  if (!item.json.reference) {
    continue;
  }

  const refPatron = item.json.reference;

  // Precio del producto base
  const productPrice = calcularPrecioConMargen(item.json.price || 0);

  results.push({
    json: {
      type: "price",
      ref_proveedor: refPatron,
      ref_variante: null,
      precioBase: productPrice.precioBase,
      price: productPrice.precioFinal
    }
  });

  // Precios de variantes
  if (item.json.variants && Array.isArray(item.json.variants)) {
    for (const variant of item.json.variants) {
      const variantPrice = calcularPrecioConMargen(variant.price || 0);

      results.push({
        json: {
          type: "price",
          ref_proveedor: refPatron,
          ref_variante: variant.reference,
          precioBase: variantPrice.precioBase,
          price: variantPrice.precioFinal
        }
      });
    }
  }
}

return results;

// Combinar datos CSV con precios de API
const csvItems = $('Parse CSV').all();
const priceItems = $input.all();

// Crear mapa de precios por ref_proveedor + ref_variante
const priceMap = new Map();

for (const item of priceItems) {
  const key = `${item.json.ref_proveedor}|${item.json.ref_variante || ""}`;
  priceMap.set(key, {
    precioBase: item.json.precioBase,
    price: item.json.price
  });
}

// Combinar CSV con precios
const result = [];

for (const item of csvItems) {
  const key = `${item.json.ref_proveedor}|${item.json.ref_variante || ""}`;
  const prices = priceMap.get(key) || { precioBase: 0, price: 0 };

  result.push({
    json: {
      ...item.json,
      precioBase: prices.precioBase,
      price: prices.price
    }
  });
}

return result;
